configuration.tbelScript:
// CONTRACT 7, 13. Gia tri lay vao metadata la CHUOI, phai parse truoc khi so sanh.
var f = parseInt(metadata.fan_level);
var lightOn = metadata.light_on == 'true';
var fanOn1 = parseFloat(metadata.shared_fan_on_1);
var fanOff1 = parseFloat(metadata.shared_fan_off_1);
var fanOn2 = parseFloat(metadata.shared_fan_on_2);
var fanOff2 = parseFloat(metadata.shared_fan_off_2);
var lightDark = parseInt(metadata.shared_light_dark);
var lightBright = parseInt(metadata.shared_light_bright);

// Quat, co hysteresis (TASKS_W2 #47).
// presence = false thi Node B uu tien tat het (CONTRACT 13 muc 1), khong gui de tranh RPC lien tuc.
var nextFan = f;
if (msg.temperature != null && msg.presence != false) {
  var t = msg.temperature;
  if (f == 0) {
    if (t >= fanOn2) { nextFan = 2; } else if (t >= fanOn1) { nextFan = 1; }
  } else if (f == 1) {
    if (t >= fanOn2) { nextFan = 2; } else if (t <= fanOff1) { nextFan = 0; }
  } else if (f == 2) {
    if (t <= fanOff1) { nextFan = 0; } else if (t <= fanOff2) { nextFan = 1; }
  }
}

// Den: co nguoi va toi thi bat, sang thi tat, con lai giu nguyen.
// Phong trong thi Node B tu tat het (CONTRACT 13), khong lo o day.
var nextLight = lightOn;
if (msg.light != null) {
  if (msg.presence == true && msg.light < lightDark) { nextLight = true; }
  else if (msg.light > lightBright) { nextLight = false; }
}

var out = {mode: metadata.mode, temperature: msg.temperature, light: msg.light, presence: msg.presence,
           fan_level: f, light_on: lightOn, next_fan: nextFan, next_light: nextLight};
return {msg: out, metadata: metadata, msgType: msgType};

// Chi gui khi dang auto va gia tri moi khac gia tri hien tai (telemetry 2 s/lan)
var r = [];
if (msg.mode != 'auto') { return r; }
if (msg.next_fan != msg.fan_level) { r.add('autoFan'); }
if (msg.next_light != msg.light_on) { r.add('autoLight'); }
return r;
